SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END rating_bucket, COUNT(rating) rating_count, MIN(rating) min_rating FROM suppliers WHERE LENGTH(supplier_name) < 14 AND (city IN ('London', 'Tokyo') OR city IN ('Bangkok', 'New York', 'Chiang Mai')) GROUP BY CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END ORDER BY rating_count DESC, min_rating DESC, rating_bucket LIMIT 20
